function updatePlayer(dt) {
  var dash = MotionDash.update(sim, { left: !!player.left, right: !!player.right, up: !!player.jump, down: false });
  updateEntity(player, dt);
  if (dash.owns && (dash.dx !== 0 || dash.dy !== 0)) {
    var totalX = dash.dx * 2;
    var totalY = dash.dy * 2;
    var span = Math.abs(totalX) > Math.abs(totalY) ? Math.abs(totalX) : Math.abs(totalY);
    var steps = Math.ceil(span / 2);
    if (steps < 1) { steps = 1; }
    var sx = totalX / steps;
    var sy = totalY / steps;
    var i, tx, ty, x0, x1, y0, y1, hit;
    for (i = 0; i < steps; i++) {
      if (sx !== 0) {
        var wantX = player.x + sx;
        var edgeX = wantX;
        if (edgeX < 0) { edgeX = 0; }
        if (edgeX > width - TILE) { edgeX = width - TILE; }
        if (edgeX !== wantX) { player.x = edgeX; sx = 0; }
        else {
          x0 = Math.floor(edgeX / TILE);
          x1 = Math.floor((edgeX + TILE - 1) / TILE);
          y0 = Math.floor(player.y / TILE);
          y1 = Math.floor((player.y + TILE - 1) / TILE);
          hit = false;
          for (ty = y0; ty <= y1; ty++) {
            for (tx = x0; tx <= x1; tx++) {
              if (tcell(tx, ty)) { hit = true; }
            }
          }
          if (!hit) { player.x = edgeX; }
          else { sx = 0; }
        }
      }
      if (sy !== 0) {
        var wantY = player.y + sy;
        var edgeY = wantY;
        if (edgeY < 0) { edgeY = 0; }
        if (edgeY > height - TILE) { edgeY = height - TILE; }
        if (edgeY !== wantY) { player.y = edgeY; sy = 0; }
        else {
          x0 = Math.floor(player.x / TILE);
          x1 = Math.floor((player.x + TILE - 1) / TILE);
          y0 = Math.floor(edgeY / TILE);
          y1 = Math.floor((edgeY + TILE - 1) / TILE);
          hit = false;
          for (ty = y0; ty <= y1; ty++) {
            for (tx = x0; tx <= x1; tx++) {
              if (tcell(tx, ty)) { hit = true; }
            }
          }
          if (!hit) { player.y = edgeY; }
          else { sy = 0; }
        }
      }
    }
  }
}
